import{_ as o,a0 as n,w as p,s as d,I as t,x as i,a1 as l,A as a,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何从命令行同时移动多种文件类型 | LCTT x X-CMD","titleTemplate":false,"description":"如何从命令行同时移动多种文件类型 | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何从命令行同时移动多种文件类型 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何从命令行同时移动多种文件类型 | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20190114 How To Move Multiple File Types Simultaneously From Commandline","title":"如何从命令行同时移动多种文件类型","tag":"201901","desc":""},"relativePath":"201901/20190114 How To Move Multiple File Types Simultaneously From Commandline.md","filePath":"[post].md"}'),h={name:"201901/20190114 How To Move Multiple File Types Simultaneously From Commandline.md"};function u(g,s,m,k,c,f){const e=n("Link");return p(),d("div",null,[s[18]||(s[18]=t("h1",{id:"如何从命令行同时移动多种文件类型",tabindex:"-1"},[i("如何从命令行同时移动多种文件类型 "),t("a",{class:"header-anchor",href:"#如何从命令行同时移动多种文件类型","aria-label":"Permalink to “如何从命令行同时移动多种文件类型”"},"​")],-1)),s[19]||(s[19]=t("p",null,[t("img",{src:"https://www.ostechnix.com/wp-content/uploads/2019/01/Move-Multiple-File-Types-720x340.png",alt:""})],-1)),t("p",null,[s[1]||(s[1]=i("前几天，我想知道如何将多个文件类型从一个目录移动（不复制）到另一个目录。我已经知道如何",-1)),l(e,{href:"https://www.ostechnix.com/find-copy-certain-type-files-one-directory-another-linux/"},{default:a(()=>[...s[0]||(s[0]=[i("查找并将某些类型的文件从一个目录复制到另一个目录",-1)])]),_:1}),s[2]||(s[2]=i("。但是，我不知道如何同时移动多种文件类型。如果你曾遇到这样的情况，我知道在类 Unix 系统中从命令行执行该操作的一个简单方法。",-1))]),s[20]||(s[20]=r(`<h3 id="同时移动多种文件类型" tabindex="-1">同时移动多种文件类型 <a class="header-anchor" href="#同时移动多种文件类型" aria-label="Permalink to “同时移动多种文件类型”">​</a></h3><p>想象一下这种场景，你在名为 <code>dir1</code> 的目录中有多种类型的文件，例如 .pdf、 .doc、 .mp3、 .mp4、 .txt 等等。我们来看看 <code>dir1</code> 的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls dir1</span></span>
<span class="line"><span>file.txt image.jpg mydoc.doc personal.pdf song.mp3 video.mp4</span></span></code></pre></div><p>你希望将某些文件类型（不是所有文件类型）移动到另一个位置。例如，假设你想将 .doc、 .pdf 和 .txt 文件一次性移动到名为 <code>dir2</code> 的另一个目录中。</p><p>要同时将 .doc、 .pdf 和 .txt 文件从 <code>dir1</code> 移动到 <code>dir2</code>，命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mv dir1/*.{doc,pdf,txt} dir2/</span></span></code></pre></div><p>很容易，不是吗？</p><p>现在让我们来查看一下 <code>dir2</code> 的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls dir2/</span></span>
<span class="line"><span>file.txt mydoc.doc personal.pdf</span></span></code></pre></div><p>看到了吗？只有 .doc、 .pdf 和 .txt 从 <code>dir1</code> 移到了 <code>dir2</code>。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2019/01/mv-command.gif" alt=""></p><p>在上面的命令中，你可以在花括号内添加任意数量的文件类型，以将它们移动到不同的目录中。它在 Bash 上非常适合我。</p><p>另一种移动多种文件类型的方法是转到源目录，在我们的例子中即为 <code>dir1</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd ~/dir1</span></span></code></pre></div><p>将你选择的文件类型移动到目的地（即 <code>dir2</code>），如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mv *.doc *.txt *.pdf /home/sk/dir2/</span></span></code></pre></div><p>要移动具有特定扩展名的所有文件，例如 .doc，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mv dir1/*.doc dir2/</span></span></code></pre></div><p>更多细节，参考 man 页：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man mv</span></span></code></pre></div><p>移动一些相同或不同的文件类型很容易！你可以在 GUI 模式下单击几下鼠标，或在 CLI 模式下使用一行命令来完成。但是，如果目录中有数千种不同的文件类型，并且希望一次将多种文件类型移动到不同的目录，这将是一项繁琐的任务。对我来说，上面的方法很容易完成工作！如果你知道任何其它一行命令可以一次移动多种文件类型，请在下面的评论部分与我们分享。我会核对并更新指南。</p><p>这些就是全部了，希望这很有用。更多好东西将要来了，敬请关注！</p><p>共勉！</p><hr>`,24)),t("p",null,[s[4]||(s[4]=i("via: ",-1)),l(e,{href:"https://www.ostechnix.com/how-to-move-multiple-file-types-simultaneously-from-commandline/"},{default:a(()=>[...s[3]||(s[3]=[i("https://www.ostechnix.com/how-to-move-multiple-file-types-simultaneously-from-commandline/",-1)])]),_:1})]),t("p",null,[s[9]||(s[9]=i("作者：",-1)),l(e,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...s[5]||(s[5]=[i("SK",-1)])]),_:1}),s[10]||(s[10]=i(" 选题：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[6]||(s[6]=[i("lujun9972",-1)])]),_:1}),s[11]||(s[11]=i(" 译者：",-1)),l(e,{href:"https://github.com/MjSeven"},{default:a(()=>[...s[7]||(s[7]=[i("MjSeven",-1)])]),_:1}),s[12]||(s[12]=i(" 校对：",-1)),l(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[8]||(s[8]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=i("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[13]||(s[13]=[i("LCTT",-1)])]),_:1}),s[16]||(s[16]=i(" 原创编译，",-1)),l(e,{href:"https://linux.cn/"},{default:a(()=>[...s[14]||(s[14]=[i("Linux中国",-1)])]),_:1}),s[17]||(s[17]=i(" 荣誉推出",-1))])])}const C=o(h,[["render",u]]);export{x as __pageData,C as default};
